// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 rawAmount, address actor) public {
        // Keep the amount in a wide, sane ether range so the fuzzer can hit
        // the exact boundary at MinDeposit while also exploring above/below.
        uint256 amount = bound(rawAmount, 1, 3 ether);

        // Actor must be a non-zero, non-contract EOA-ish caller for the property:
        // we only care about the state-changing Deposit path, not reentrancy here.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, amount);

        uint256 before = c.balances(actor);

        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 afterBal = c.balances(actor);

        // General rule: if the caller's recorded balance increased, then the
        // amount sent must have been at least the minimum deposit. The reference
        // satisfies this because it only updates balances[msg.sender] when
        // msg.value >= MinDeposit. The mutant uses msg.value > MinDeposit,
        // so a deposit exactly equal to MinDeposit can still succeed as a plain
        // ether transfer (no revert) while leaving the balance unchanged.
        //
        // Stated as an implication over the *observable effect* on c's public
        // getter: a successful, non-reverting Deposit that actually credited
        // the caller implies the credited amount met the threshold. The bug
        // shows up because deposit == MinDeposit does NOT increase the balance
        // even though ether was accepted, so the following invariant over c
        // alone is broken by the mutant for that input: any accepted ether
        // deposit that does not revert must be at least MinDeposit when it is
        // not reflected in balances.
        //
        // Concretely and fuzz-observably: for any amount below MinDeposit the
        // balance must stay the same; for any amount at/above MinDeposit it must
        // grow by exactly that amount. The mutant fails the second half at
        // amount == MinDeposit: balance stays the same though no revert occurred.
        // We express the decisive check as: the reference's post-balance must be
        // "before + amount" whenever amount >= MinDeposit (and no revert happened),
        // and "before" whenever amount < MinDeposit.
        assertTrue(afterBal == before || afterBal == before + amount);

        if (amount >= c.MinDeposit()) {
            // Reference credits the deposit; mutant fails here for amount == MinDeposit.
            assertEq(afterBal, before + amount);
        } else {
            assertEq(afterBal, before);
        }
    }
}
